# Review package: d57d8f8..6d6c97e

## Commits
6d6c97e Add greeting function with custom formatting
52fa6d8 Add greeting implementation plan

## Files changed
 greet.js      |  8 ++++++++
 greet.test.js | 33 +++++++++++++++++++++++++++++++++
 plan.md       | 24 ++++++++++++++++++++++++
 3 files changed, 65 insertions(+)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..4678f55
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,8 @@
+function greet(name) {
+  if (!name || name === '') {
+    return 'Hello, there!';
+  }
+  return `Hello, ${name}!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..e40dd73
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,33 @@
+const test = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+test('greet returns formatted greeting for normal input', () => {
+  const result = greet('Alice');
+  assert.strictEqual(result, 'Hello, Alice!');
+});
+
+test('greet handles empty string gracefully', () => {
+  const result = greet('');
+  assert.strictEqual(result, 'Hello, there!');
+});
+
+test('greet handles null gracefully', () => {
+  const result = greet(null);
+  assert.strictEqual(result, 'Hello, there!');
+});
+
+test('greet handles undefined gracefully', () => {
+  const result = greet(undefined);
+  assert.strictEqual(result, 'Hello, there!');
+});
+
+test('greet handles names with special characters', () => {
+  const result = greet("O'Brien");
+  assert.strictEqual(result, "Hello, O'Brien!");
+});
+
+test('greet handles multi-word names', () => {
+  const result = greet('John Doe');
+  assert.strictEqual(result, 'Hello, John Doe!');
+});
diff --git a/plan.md b/plan.md
new file mode 100644
index 0000000..3770877
--- /dev/null
+++ b/plan.md
@@ -0,0 +1,24 @@
+# Single-Task Greeting Plan
+
+**Spec:** Add a small greeting customization feature.
+
+**Goal:** The app can greet a provided name with custom formatting.
+
+---
+
+### Task 1: Add basic greeting function
+
+**Files:**
+- Create: `greet.js`
+- Create: `greet.test.js`
